import React, { useState } from 'react';
import OpenAI from 'openai';

const openai = new OpenAI({
  apiKey: process.env.REACT_APP_OPENAI_API_KEY,
  dangerouslyAllowBrowser: true
});

const TranscriptAnalyzer = () => {
  const [transcript, setTranscript] = useState('');
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(false);

  const analyzeWithAI = async (text) => {
    try {
      setLoading(true);
      const response = await openai.chat.completions.create({
        model: "gpt-4",
        messages: [{
          role: "system",
          content: "Return a structured analysis in JSON format like this: {\"tone\": \"string\", \"metrics\": [\"string\"], \"challenge\": \"string\", \"weeklyFocus\": {\"focus\": \"string\", \"steps\": [\"string\"]}}"
        }, {
          role: "user",
          content: text
        }],
        temperature: 0.7,
        response_format: { type: "json_object" }
      });
  
      console.log('Raw response:', response.choices[0].message.content);
      return JSON.parse(response.choices[0].message.content);
    } catch (error) {
      console.error('Error:', error);
      return null;
    } finally {
      setLoading(false);
    }
  };

  const analyzeTranscript = async () => {
    const aiAnalysis = await analyzeWithAI(transcript);
    if (aiAnalysis) {
      setSummary(aiAnalysis);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8 px-4">
      <div className="max-w-3xl mx-auto bg-white rounded-xl shadow-lg p-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-6">1:1 Meeting Analysis</h1>
        
        <div className="space-y-6">
          <textarea 
            className="w-full h-64 p-4 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            placeholder="Paste your meeting transcript here..."
            value={transcript}
            onChange={(e) => setTranscript(e.target.value)}
          />
          
          <button
            className={`w-full py-3 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 transition-colors ${loading ? 'opacity-50 cursor-not-allowed' : ''}`}
            onClick={analyzeTranscript}
            disabled={loading}
          >
            {loading ? 'Analyzing...' : 'Analyze Transcript'}
          </button>

          {summary && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-8">
              <div className="bg-blue-50 p-6 rounded-lg">
                <h3 className="text-lg font-semibold text-blue-900">Conversation Tone</h3>
                <p className="mt-2 text-blue-800">{summary.tone}</p>
              </div>
              
              <div className="bg-green-50 p-6 rounded-lg">
                <h3 className="text-lg font-semibold text-green-900">Key Metrics</h3>
                <ul className="mt-2 space-y-2 text-green-800">
                  {summary.metrics.map((metric, i) => (
                    <li key={i}>• {metric}</li>
                  ))}
                </ul>
              </div>
              
              <div className="bg-purple-50 p-6 rounded-lg">
                <h3 className="text-lg font-semibold text-purple-900">Main Challenge</h3>
                <p className="mt-2 text-purple-800">{summary.challenge}</p>
              </div>
              
              <div className="bg-orange-50 p-6 rounded-lg col-span-2">
                <h3 className="text-lg font-semibold text-orange-900">Weekly Focus & Action Plan</h3>
                <div className="mt-2 text-orange-800">
                  <p className="font-medium">Focus: {summary.weeklyFocus.focus}</p>
                  <ul className="mt-2 space-y-1">
                    {summary.weeklyFocus.steps.map((step, i) => (
                      <li key={i}>• {step}</li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TranscriptAnalyzer;
